// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// ChangeInitialPassword Replace an administrator-issued initial password
	// (POST /auth/change-initial-password)
	ChangeInitialPassword(ctx context.Context, request ChangeInitialPasswordRequestObject) (ChangeInitialPasswordResponseObject, error)
	// ForgotPassword Send a password reset link
	// (POST /auth/forgot-password)
	ForgotPassword(ctx context.Context, request ForgotPasswordRequestObject) (ForgotPasswordResponseObject, error)
	// Login Exchange credentials for a session
	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)
	// Logout Revoke the current session
	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)
	// GetCurrentUser The user behind the current session
	// (GET /auth/me)
	GetCurrentUser(ctx context.Context, request GetCurrentUserRequestObject) (GetCurrentUserResponseObject, error)
	// Register Create an account and start a session
	// (POST /auth/register)
	Register(ctx context.Context, request RegisterRequestObject) (RegisterResponseObject, error)
	// ResendVerification Send a fresh verification link
	// (POST /auth/resend-verification)
	ResendVerification(ctx context.Context, request ResendVerificationRequestObject) (ResendVerificationResponseObject, error)
	// ResetPassword Set a new password from a reset link
	// (POST /auth/reset-password)
	ResetPassword(ctx context.Context, request ResetPasswordRequestObject) (ResetPasswordResponseObject, error)
	// VerifyEmail Confirm an address with the emailed one-time code
	// (POST /auth/verify-email)
	VerifyEmail(ctx context.Context, request VerifyEmailRequestObject) (VerifyEmailResponseObject, error)
	// GetHealth Liveness and database reachability
	// (GET /health)
	GetHealth(ctx context.Context, request GetHealthRequestObject) (GetHealthResponseObject, error)
	// SearchMessages Search messages visible to the signed-in user
	// (GET /messages/search)
	SearchMessages(ctx context.Context, request SearchMessagesRequestObject) (SearchMessagesResponseObject, error)
	// UploadAttachment Upload a file to attach to a later message
	// (POST /v1/attachments)
	UploadAttachment(ctx context.Context, request UploadAttachmentRequestObject) (UploadAttachmentResponseObject, error)
	// SendEmail Queue a message for sending
	// (POST /v1/emails)
	SendEmail(ctx context.Context, request SendEmailRequestObject) (SendEmailResponseObject, error)
	// GetEmail One message
	// (GET /v1/emails/{id})
	GetEmail(ctx context.Context, request GetEmailRequestObject) (GetEmailResponseObject, error)
	// GetApiKeyWorkspace The workspace the API key belongs to
	// (GET /v1/workspace)
	GetApiKeyWorkspace(ctx context.Context, request GetApiKeyWorkspaceRequestObject) (GetApiKeyWorkspaceResponseObject, error)
	// ListWorkspaces Workspaces the signed-in user belongs to
	// (GET /workspaces)
	ListWorkspaces(ctx context.Context, request ListWorkspacesRequestObject) (ListWorkspacesResponseObject, error)
	// CreateWorkspace Create a workspace
	// (POST /workspaces)
	CreateWorkspace(ctx context.Context, request CreateWorkspaceRequestObject) (CreateWorkspaceResponseObject, error)
	// DeleteWorkspace Delete a workspace and everything under it
	// (DELETE /workspaces/{slug})
	DeleteWorkspace(ctx context.Context, request DeleteWorkspaceRequestObject) (DeleteWorkspaceResponseObject, error)
	// GetWorkspace One workspace by slug
	// (GET /workspaces/{slug})
	GetWorkspace(ctx context.Context, request GetWorkspaceRequestObject) (GetWorkspaceResponseObject, error)
	// ListApiKeys The workspace's API keys
	// (GET /workspaces/{slug}/api-keys)
	ListApiKeys(ctx context.Context, request ListApiKeysRequestObject) (ListApiKeysResponseObject, error)
	// CreateApiKey Issue an API key
	// (POST /workspaces/{slug}/api-keys)
	CreateApiKey(ctx context.Context, request CreateApiKeyRequestObject) (CreateApiKeyResponseObject, error)
	// RevokeApiKey Revoke an API key
	// (DELETE /workspaces/{slug}/api-keys/{keyId})
	RevokeApiKey(ctx context.Context, request RevokeApiKeyRequestObject) (RevokeApiKeyResponseObject, error)
	// UploadWorkspaceAttachment Upload a file as a workspace member
	// (POST /workspaces/{slug}/attachments)
	UploadWorkspaceAttachment(ctx context.Context, request UploadWorkspaceAttachmentRequestObject) (UploadWorkspaceAttachmentResponseObject, error)
	// ListDomains Mail domains owned by the workspace
	// (GET /workspaces/{slug}/domains)
	ListDomains(ctx context.Context, request ListDomainsRequestObject) (ListDomainsResponseObject, error)
	// AddDomain Claim a domain
	// (POST /workspaces/{slug}/domains)
	AddDomain(ctx context.Context, request AddDomainRequestObject) (AddDomainResponseObject, error)
	// DeleteDomain Release a domain
	// (DELETE /workspaces/{slug}/domains/{domain})
	DeleteDomain(ctx context.Context, request DeleteDomainRequestObject) (DeleteDomainResponseObject, error)
	// GetDomain One domain
	// (GET /workspaces/{slug}/domains/{domain})
	GetDomain(ctx context.Context, request GetDomainRequestObject) (GetDomainResponseObject, error)
	// UpdateDomain Make a domain the workspace default
	// (PATCH /workspaces/{slug}/domains/{domain})
	UpdateDomain(ctx context.Context, request UpdateDomainRequestObject) (UpdateDomainResponseObject, error)
	// RotateDkimKey Mint a replacement DKIM key
	// (POST /workspaces/{slug}/domains/{domain}/dkim/rotate)
	RotateDkimKey(ctx context.Context, request RotateDkimKeyRequestObject) (RotateDkimKeyResponseObject, error)
	// VerifyDomain Check the DNS challenge now
	// (POST /workspaces/{slug}/domains/{domain}/verify)
	VerifyDomain(ctx context.Context, request VerifyDomainRequestObject) (VerifyDomainResponseObject, error)
	// SendWorkspaceEmail Send a message as a signed-in person
	// (POST /workspaces/{slug}/emails)
	SendWorkspaceEmail(ctx context.Context, request SendWorkspaceEmailRequestObject) (SendWorkspaceEmailResponseObject, error)
	// GetWorkspaceEmail Read a queued message and its sending status as a workspace member
	// (GET /workspaces/{slug}/emails/{id})
	GetWorkspaceEmail(ctx context.Context, request GetWorkspaceEmailRequestObject) (GetWorkspaceEmailResponseObject, error)
	// ListMailboxes Addresses this workspace receives mail at
	// (GET /workspaces/{slug}/mailboxes)
	ListMailboxes(ctx context.Context, request ListMailboxesRequestObject) (ListMailboxesResponseObject, error)
	// CreateMailbox Start receiving mail at an address
	// (POST /workspaces/{slug}/mailboxes)
	CreateMailbox(ctx context.Context, request CreateMailboxRequestObject) (CreateMailboxResponseObject, error)
	// ListMessages Received mail in Inbox or Junk, newest first
	// (GET /workspaces/{slug}/mailboxes/{mailboxId}/messages)
	ListMessages(ctx context.Context, request ListMessagesRequestObject) (ListMessagesResponseObject, error)

	// (PUT /workspaces/{slug}/mailboxes/{mailboxId}/owner)
	AssignMailboxOwner(ctx context.Context, request AssignMailboxOwnerRequestObject) (AssignMailboxOwnerResponseObject, error)

	// (DELETE /workspaces/{slug}/mailboxes/{mailboxId}/smtp-password)
	DeleteMailboxSMTPPassword(ctx context.Context, request DeleteMailboxSMTPPasswordRequestObject) (DeleteMailboxSMTPPasswordResponseObject, error)
	// SetMailboxSMTPPassword Owner delegates send-only SMTP access with a mailbox password
	// (PUT /workspaces/{slug}/mailboxes/{mailboxId}/smtp-password)
	SetMailboxSMTPPassword(ctx context.Context, request SetMailboxSMTPPasswordRequestObject) (SetMailboxSMTPPasswordResponseObject, error)
	// ListMembers Owner-only workspace member management
	// (GET /workspaces/{slug}/members)
	ListMembers(ctx context.Context, request ListMembersRequestObject) (ListMembersResponseObject, error)
	// AddMember Owner-only workspace member management
	// (POST /workspaces/{slug}/members)
	AddMember(ctx context.Context, request AddMemberRequestObject) (AddMemberResponseObject, error)
	// RemoveMember Owner-only workspace member management
	// (DELETE /workspaces/{slug}/members/{userId})
	RemoveMember(ctx context.Context, request RemoveMemberRequestObject) (RemoveMemberResponseObject, error)
	// UpdateMember Owner-only workspace member management
	// (PATCH /workspaces/{slug}/members/{userId})
	UpdateMember(ctx context.Context, request UpdateMemberRequestObject) (UpdateMemberResponseObject, error)
	// GetMessage One received message
	// (GET /workspaces/{slug}/messages/{messageId})
	GetMessage(ctx context.Context, request GetMessageRequestObject) (GetMessageResponseObject, error)
	// MarkMessageRead Mark a message read
	// (POST /workspaces/{slug}/messages/{messageId})
	MarkMessageRead(ctx context.Context, request MarkMessageReadRequestObject) (MarkMessageReadResponseObject, error)

	// (GET /workspaces/{slug}/messages/{messageId}/attachments/{attachmentId})
	DownloadReceivedAttachment(ctx context.Context, request DownloadReceivedAttachmentRequestObject) (DownloadReceivedAttachmentResponseObject, error)

	// (PUT /workspaces/{slug}/messages/{messageId}/folder)
	MoveReceivedMessage(ctx context.Context, request MoveReceivedMessageRequestObject) (MoveReceivedMessageResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// ChangeInitialPassword operation middleware
func (sh *strictHandler) ChangeInitialPassword(w http.ResponseWriter, r *http.Request) {
	var request ChangeInitialPasswordRequestObject

	var body ChangeInitialPasswordJSONRequestBody
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		sh.options.RequestErrorHandlerFunc(w, r, fmt.Errorf("can't decode JSON body: %w", err))
		return
	}
	request.Body = &body

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.ChangeInitialPassword(ctx, request.(ChangeInitialPasswordRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "ChangeInitialPassword")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(ChangeInitialPasswordResponseObject); ok {
		if err := validResponse.VisitChangeInitialPasswordResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

